// gcc -O2 Arzopa_DeepSeek.c -o Arzopa_DeepSeek -lm

/*
Title	Reference
8 colour bars	Primary / secondary saturations
Grayscale 32 steps	Banding / gamma linearity
R, G, B gradients	Channel response
Amber spectrum + 8 swatches	Warm hue range, dark→bright
Carmine spectrum + 8 swatches	Deep red / magenta hue range
8 sharpness patterns	1px checker, V/H lines, dots, diagonal, crosshatch, concentric rings, variable mesh
Text at 1px, 2px, 3px, 5px, 8px	Fine / small / medium / large glyph rendering
Amber + carmine text samples	How each hue reads at text scale
24-patch colour checker	Reference colour accuracy (X-Rite style)
Everything fills the 2560×1600 canvas with only the mandated 1px white frame and 15px black inset untouched.
*/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

#define W 2560
#define H 1600
#define ROW_SIZE ((W * 3 + 3) & ~3)

typedef struct { unsigned char b, g, r; } RGB;
typedef struct { char c; unsigned char rows[7]; } Glyph;
typedef struct { char c; unsigned char rows[16]; } Glyph16;
typedef struct { char c; unsigned char rows[14]; } Glyph14;

static unsigned char *img;

static RGB rgb(unsigned char r, unsigned char g, unsigned char b) {
    RGB c; c.r = r; c.g = g; c.b = b; return c;
}

static void set_pixel(int x, int y, RGB c) {
    if (x < 0 || x >= W || y < 0 || y >= H) return;
    int row = H - 1 - y;
    unsigned char *p = img + row * ROW_SIZE + x * 3;
    p[0] = c.b; p[1] = c.g; p[2] = c.r;
}

static void fill_rect(int x, int y, int w, int h, RGB c) {
    if (w <= 0 || h <= 0) return;
    for (int yy = y; yy < y + h; yy++)
        for (int xx = x; xx < x + w; xx++)
            set_pixel(xx, yy, c);
}

static void draw_rect(int x, int y, int w, int h, RGB c) {
    if (w <= 0 || h <= 0) return;
    for (int i = 0; i < w; i++) { set_pixel(x+i, y, c); set_pixel(x+i, y+h-1, c); }
    for (int i = 0; i < h; i++) { set_pixel(x, y+i, c); set_pixel(x+w-1, y+i, c); }
}

static void fill_gradient_h(int x, int y, int w, int h, RGB a, RGB b) {
    if (w <= 0 || h <= 0) return;
    for (int i = 0; i < w; i++) {
        float t = (w > 1) ? (float)i / (float)(w - 1) : 0.0f;
        RGB c = rgb(
            (unsigned char)(a.r + (b.r - a.r) * t),
            (unsigned char)(a.g + (b.g - a.g) * t),
            (unsigned char)(a.b + (b.b - a.b) * t));
        fill_rect(x + i, y, 1, h, c);
    }
}

static void fill_gradient_h3(int x, int y, int w, int h, RGB a, RGB b, RGB c) {
    int w1 = w / 2;
    fill_gradient_h(x, y, w1, h, a, b);
    fill_gradient_h(x + w1, y, w - w1, h, b, c);
}

