static Glyph *find_glyph(char c) {
    for (size_t i = 0; i < sizeof(font)/sizeof(font[0]); i++)
        if (font[i].c == c) return &font[i];
    return &font[0];
}

static Glyph16 *find_glyph16(char c) {
    for (size_t i = 0; i < sizeof(font16)/sizeof(font16[0]); i++)
        if (font16[i].c == c) return &font16[i];
    return &font16[0];
}

static Glyph14 *find_glyph14(char c) {
    for (size_t i = 0; i < sizeof(font14)/sizeof(font14[0]); i++)
        if (font14[i].c == c) return &font14[i];
    return &font14[0];
}

static void draw_char(int x, int y, char c, int scale, RGB color) {
    Glyph *g = find_glyph(c);
    for (int row = 0; row < 7; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 5; col++)
            if (bits & (1 << (4 - col)))
                fill_rect(x + col*scale, y + row*scale, scale, scale, color);
    }
}

static void draw_char16(int x, int y, char c, int scale, RGB color) {
    Glyph16 *g = find_glyph16(c);
    for (int row = 0; row < 16; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 8; col++)
            if (bits & (1 << ((8-1) - col)))
                fill_rect(x + col*scale, y + row*scale, scale, scale, color);
    }
}

static void draw_char14(int x, int y, char c, int scale, RGB color) {
    Glyph14 *g = find_glyph14(c);
    for (int row = 0; row < 14; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 8; col++)
            if (bits & (1 << ((8-1) - col)))
                fill_rect(x + col*scale, y + row*scale, scale, scale, color);
    }
}

static void draw_char16x2(int x, int y, char c, int scale, RGB color) {
    Glyph16 *g = find_glyph16(c);
    for (int row = 0; row < 16; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 8; col++)
            if (bits & (1 << ((8-1) - col)))
                fill_rect(x + col*scale, y + row*scale*2, scale, scale*2, color);
    }
}

static void draw_char16x3(int x, int y, char c, int scale, RGB color) {
    Glyph16 *g = find_glyph16(c);
    for (int row = 0; row < 16; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 8; col++)
            if (bits & (1 << ((8-1) - col)))
                fill_rect(x + col*scale, y + row*scale*3, scale, scale*3, color);
    }
}

static void draw_char16x3_2H(int x, int y, char c, int scale, RGB color) {
    Glyph16 *g = find_glyph16(c);
    for (int row = 0; row < 16; row++) {
        unsigned char bits = g->rows[row];
        for (int col = 0; col < 8; col++)
            if (bits & (1 << ((8-1) - col)))
                fill_rect(x + col*scale*2, y + row*scale*3, scale, scale*3, color);
    }
}

static void draw_text16x3_2H(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char16x3_2H(cx, y, *p, scale, color); cx += (16+1)*scale; }
}

static void draw_text(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char(cx, y, *p, scale, color); cx += 6*scale; }
}

static void draw_text16(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char16(cx, y, *p, scale, color); cx += (8+1)*scale; }
}

static void draw_text14(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char14(cx, y, *p, scale, color); cx += (8+1)*scale; }
}

static void draw_text16x2(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char16x2(cx, y, *p, scale, color); cx += (8+1)*scale; }
}

static void draw_text16x3(int x, int y, const char *text, int scale, RGB color) {
    int cx = x;
    for (const char *p = text; *p; p++) { draw_char16x3(cx, y, *p, scale, color); cx += (8+1)*scale; }
}

/* Two-stop gradient text: colour interpolated character-by-character */
static void draw_text_gradient(int x, int y, const char *text, int scale, RGB a, RGB b) {
    int len = (int)strlen(text);
    int cx = x;
    for (int i = 0; i < len; i++) {
        float t = (len > 1) ? (float)i / (float)(len - 1) : 0.0f;
        RGB c = rgb(
            (unsigned char)(a.r + (b.r - a.r) * t),
            (unsigned char)(a.g + (b.g - a.g) * t),
            (unsigned char)(a.b + (b.b - a.b) * t));
        draw_char16x3_2H(cx, y, text[i], scale, c);
        //cx += (5+1) * scale;
        cx += (16+1) * scale;
    }
}

/* Multi-stop gradient text: pass any number of colour stops */
static void draw_text_gradient_multi(int x, int y, const char *text, int scale,
                                     RGB *stops, int nstops) {
    if (nstops < 2) return;
    int len = (int)strlen(text);
    int cx = x;
    for (int i = 0; i < len; i++) {
        float t = (len > 1) ? (float)i / (float)(len - 1) : 0.0f;
        float seg = t * (nstops - 1);
        int   s   = (int)seg;
        if (s >= nstops - 1) s = nstops - 2;
        float lt  = seg - s;
        RGB a = stops[s], b = stops[s + 1];
        RGB c = rgb(
            (unsigned char)(a.r + (b.r - a.r) * lt),
            (unsigned char)(a.g + (b.g - a.g) * lt),
            (unsigned char)(a.b + (b.b - a.b) * lt));
        draw_char16x3_2H(cx, y, text[i], scale, c);
        //cx += (5+1) * scale;
        cx += (16+1) * scale;
    }
}

static int text_width(const char *text, int scale) { return (int)strlen(text) * 6 * scale; }
static int text_width16(const char *text, int scale) { return (int)strlen(text) * (8+1) * scale; }

/* ---------------- Patterns ---------------- */
static void pat_checker(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, ((i + j) & 1) ? a : b);
}
static void pat_vlines(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, (i & 1) ? a : b);
}
static void pat_hlines(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, (j & 1) ? a : b);
}
static void pat_dots(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, ((i & 1) == 0 && (j & 1) == 0) ? a : b);
}
static void pat_diagonal(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, (((i + j) >> 1) & 1) ? a : b);
}
static void pat_cross(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++)
        set_pixel(x+i, y+j, ((i & 3) == 0 || (j & 3) == 0) ? a : b);
}
static void pat_rings(int x, int y, int w, int h, RGB a, RGB b) {
    float cx = w/2.0f, cy = h/2.0f;
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++) {
        float dx = i - cx, dy = j - cy;
        int ring = (int)(sqrtf(dx*dx + dy*dy) / 5.0f);
        set_pixel(x+i, y+j, (ring & 1) ? a : b);
    }
}
static void pat_mesh(int x, int y, int w, int h, RGB a, RGB b) {
    for (int j = 0; j < h; j++) for (int i = 0; i < w; i++) {
        int pitch = 3 + (i * 12) / w;   /* pitch sweeps 3..9 */
        set_pixel(x+i, y+j, ((i % pitch == 0) || (j % pitch == 0)) ? a : b);
    }
}

/* ---------------- BMP writer ---------------- */
static void write_bmp(const char *filename, unsigned char *data, int w, int h) {
    int row_size = (w * 3 + 3) & ~3;
    uint32_t image_size = (uint32_t)row_size * h;
    uint32_t file_size  = 54 + image_size;
    unsigned char header[54] = {0};
    header[0] = 'B'; header[1] = 'M';
    memcpy(header + 2,  &file_size, 4);
    uint32_t offset = 54;   memcpy(header + 10, &offset, 4);
    uint32_t dib    = 40;   memcpy(header + 14, &dib, 4);
    int32_t  iw     = w;    memcpy(header + 18, &iw, 4);
    int32_t  ih     = h;    memcpy(header + 22, &ih, 4);
    uint16_t planes = 1;    memcpy(header + 26, &planes, 2);
    uint16_t bpp    = 24;   memcpy(header + 28, &bpp, 2);
    uint32_t comp   = 0;    memcpy(header + 30, &comp, 4);
    memcpy(header + 34, &image_size, 4);
    uint32_t ppm    = 2835; memcpy(header + 38, &ppm, 4);
    memcpy(header + 42, &ppm, 4);

    FILE *f = fopen(filename, "wb");
    if (!f) { perror("fopen"); exit(1); }
    fwrite(header, 1, 54, f);
    fwrite(data, 1, image_size, f);
    fclose(f);
}

